// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint96 feeAmount, uint256 seed) public {
        // Deploy a minimal ERC20-like token whose transfer records the amount received.
        RecorderToken tok = new RecorderToken();

        // Seed some unclaimed fees for this asset by having the token simply
        // sit in C's balance and setting the internal accounting via the public
        // withdrawFees path is not possible, so instead we set state by making
        // the recorder token's transfer observable.  unclaimedFees is private to
        // the contract, but it only changes through withdrawFees (which zeroes
        // it).  To get a nonzero stored value we must first accrue fees via a
        // fillOrder or direct manipulation.  Since neither is available, we use
        // the fact that withdrawFees reads unclaimedFees[asset] first.
        //
        // The only way to make unclaimedFees[asset] nonzero through the public
        // surface is to fill an order with a nonzero fee, which requires a valid
        // signature.  Instead we observe the difference directly: after a call
        // with zero stored fees both versions transfer 0, so the bug is masked.
        // We therefore use a helper that makes the token's transfer amount the
        // thing we compare against the drop in unclaimedFees.  With unclaimedFees
        // zero the drop is zero and transfer is zero in both, so no difference.
        // To expose the bug we need unclaimedFees nonzero.  That is impossible
        // without a signed order, so we craft one.
        //
        // Build a minimal Order with fee accrued via fillOrder.
        // Fee is 0 in setUp, so set a nonzero fee first.
        uint256 newFee = (uint256(seed) % 29) + 1; // 1..29, < 30
        c.setFee(newFee);

        // Create a long call order maker signs.  We need a signature over
        // hashOrder(order).
        uint256 makerPk = uint256(keccak256(abi.encode(seed, "maker"))) % 0xfffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff0 + 1;
        address maker = vm.addr(makerPk);

        PuttyV2.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(tok);
        order.strike = 1;
        order.premium = uint256(feeAmount) + 1; // premium > 0 so fee > 0
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = seed;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerPk, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        // Give maker enough tokens and approve C.
        tok.mint(maker, order.premium + 1);
        vm.prank(maker);
        tok.approve(address(c), type(uint256).max);

        uint256[] memory floors = new uint256[](0);
        vm.prank(address(this));
        c.fillOrder(order, signature, floors);

        // Now C holds feeAmount of tok as unclaimedFees.
        uint256 expectedFee = (order.premium * newFee) / 1000;
        // Ensure nonzero fee.
        vm.assume(expectedFee > 0);

        // Read stored fees before withdrawal.
        uint256 beforeFees = c.unclaimedFees(address(tok));

        // Reset recorder's view.
        tok.reset();

        // Withdraw fees to a recipient; P transfers beforeFees, M transfers 0.
        address recipient = address(0xBEEF);
        c.withdrawFees(address(tok), recipient);

        uint256 afterFees = c.unclaimedFees(address(tok));
        uint256 transferred = tok.lastAmount();

        // Rule: the amount actually transferred out equals the drop in stored fees.
        assertTrue(transferred == beforeFees - afterFees);
    }
}

contract RecorderToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => bool)) public allowed;
    uint256 public lastAmount;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256) external returns (bool) {
        allowed[msg.sender][spender] = true;
        return true;
    }

    function reset() external {
        lastAmount = 0;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        lastAmount = amount;
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowed[from][msg.sender], "not allowed");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
